import { Options, Replies } from 'amqplib';

interface QueueClientConfig {
    /**
     * RabbitMQ connection URL.
     *
     * Example:
     * amqp://guest:guest@localhost:5672
     */
    readonly url: string;
    /**
     * Name displayed in the RabbitMQ Management UI.
     */
    readonly connectionName?: string;
    /**
     * Heartbeat interval in seconds.
     */
    readonly heartbeat?: number;
    /**
     * Maximum reconnect attempts.
     *
     * Undefined means retry forever.
     */
    readonly maxReconnectAttempts?: number;
    /**
     * Initial reconnect delay in milliseconds.
     *
     * @default 1000
     */
    readonly reconnectDelay?: number;
    /**
     * Maximum reconnect delay in milliseconds.
     *
     * @default 30000
     */
    readonly maxReconnectDelay?: number;
    /**
     * Automatically create queues that don't exist.
     *
     * @default true
     */
    readonly autoCreateQueues?: boolean;
    /**
     * Automatically recreate queues after reconnect.
     *
     * @default true
     */
    readonly autoRecover?: boolean;
}

declare enum QueueClientState {
    DISCONNECTED = "DISCONNECTED",
    CONNECTING = "CONNECTING",
    CONNECTED = "CONNECTED",
    RECONNECTING = "RECONNECTING",
    CLOSED = "CLOSED"
}

declare class QueueClient {
    private readonly config;
    private connectionManager;
    private readonly queues;
    private state;
    constructor(config: QueueClientConfig);
    get connected(): boolean;
    get currentState(): QueueClientState;
    connect(): Promise<void>;
    publish<T>(queueName: string, message: T, options?: Options.Publish): Promise<boolean>;
    subscribe<T>(queueName: string, handler: (message: T) => Promise<void> | void, options?: Options.Consume): Promise<Replies.Consume>;
    close(): Promise<void>;
    private getQueue;
    private registerConnectionHandlers;
    private reconnect;
}

declare function createQueueClient(config: QueueClientConfig): QueueClient;

export { QueueClient, type QueueClientConfig, createQueueClient };
